package au.aumanet.app;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Fixed/bounded internet data protocol inside mutually authenticated TLS. */
final class InternetWire{
 static final int TCP=1,UDP=2,PING=0,MAX_UDP=65507;static final byte[] MAGIC="AUMINET2".getBytes(StandardCharsets.US_ASCII);
 static final class Address{
  final String host;final int port;final int type;final byte[] raw;
  Address(int type,byte[] raw,int port)throws IOException{if(port<0||port>65535||!(type==1&&raw.length==4||type==4&&raw.length==16||type==3&&raw.length>=1&&raw.length<=253))throw new IOException("Invalid destination");this.type=type;this.raw=raw.clone();this.port=port;host=type==3?new String(raw,StandardCharsets.US_ASCII):InetAddress.getByAddress(raw).getHostAddress();if(type==3&&!host.matches("[A-Za-z0-9._-]{1,253}"))throw new IOException("Invalid hostname");}
  String key(){return host+":"+port;}
 }
 static Address readAddress(DataInputStream in)throws IOException{int type=in.readUnsignedByte(),n=type==1?4:type==4?16:type==3?in.readUnsignedByte():0;if(n==0||n>253)throw new IOException("Invalid destination");byte[] raw=new byte[n];in.readFully(raw);return new Address(type,raw,in.readUnsignedShort());}
 static void writeAddress(DataOutputStream out,Address address)throws IOException{out.writeByte(address.type);if(address.type==3)out.writeByte(address.raw.length);out.write(address.raw);out.writeShort(address.port);}
 static Address actual(InetAddress ip,int port)throws IOException{return new Address(ip.getAddress().length==4?1:4,ip.getAddress(),port);}
 static void header(DataOutputStream out,String group,long epoch,String session,int kind,Address target)throws IOException{out.write(MAGIC);out.write(hex(group,16));out.writeLong(epoch);out.write(hex(session,16));out.writeByte(kind);if(kind==TCP){if(target==null||target.port<1)throw new IOException("Invalid destination");writeAddress(out,target);}out.flush();}
 static int acceptHeader(DataInputStream in,String group,long epoch,String session)throws IOException{byte[] magic=new byte[8],g=new byte[16],s=new byte[16];in.readFully(magic);in.readFully(g);long e=in.readLong();in.readFully(s);int kind=in.readUnsignedByte();if(!Arrays.equals(magic,MAGIC)||!Arrays.equals(g,hex(group,16))||e!=epoch||!Arrays.equals(s,hex(session,16))||kind<0||kind>2)throw new IOException("Internet sharing scope changed");return kind;}
 static byte[] hex(String text,int bytes)throws IOException{if(text==null||!text.matches("[a-f0-9]{"+bytes*2+"}"))throw new IOException("Invalid internet scope");byte[] result=new byte[bytes];for(int i=0;i<bytes;i++)result[i]=(byte)Integer.parseInt(text.substring(i*2,i*2+2),16);return result;}
 static final class Datagram{final Address address;final byte[] payload;Datagram(Address a,byte[] p){address=a;payload=p;}}
 static void datagram(DataOutputStream out,Address address,byte[] payload,int size)throws IOException{if(size<0||size>MAX_UDP||size>payload.length)throw new IOException("UDP limit");ByteArrayOutputStream buffer=new ByteArrayOutputStream(size+260);DataOutputStream body=new DataOutputStream(buffer);writeAddress(body,address);body.write(payload,0,size);byte[] encoded=buffer.toByteArray();synchronized(out){out.writeInt(encoded.length);out.write(encoded);out.flush();}}
 static final class StreamReader{private final byte[] prefix=new byte[4];private int prefixBytes,received;private byte[] body;byte[] read(DataInputStream in)throws IOException{while(prefixBytes<4){int n=in.read(prefix,prefixBytes,4-prefixBytes);if(n<0)throw new EOFException();prefixBytes+=n;}if(body==null){int size=java.nio.ByteBuffer.wrap(prefix).getInt();if(size<0||size>4096)throw new IOException("TCP frame limit");body=new byte[size];}while(received<body.length){int n=in.read(body,received,body.length-received);if(n<0)throw new EOFException();received+=n;}byte[] result=body;body=null;prefixBytes=received=0;return result;}}
 static final class DatagramReader{private final byte[] prefix=new byte[4];private int prefixBytes,received;private byte[] body;Datagram read(DataInputStream in)throws IOException{while(prefixBytes<4){int n=in.read(prefix,prefixBytes,4-prefixBytes);if(n<0)throw new EOFException();prefixBytes+=n;}if(body==null){int size=java.nio.ByteBuffer.wrap(prefix).getInt();if(size<7||size>MAX_UDP+260)throw new IOException("UDP limit");body=new byte[size];}while(received<body.length){int n=in.read(body,received,body.length-received);if(n<0)throw new EOFException();received+=n;}ByteArrayInputStream bytes=new ByteArrayInputStream(body);Address address=readAddress(new DataInputStream(bytes));byte[] payload=new byte[bytes.available()];if(payload.length>MAX_UDP)throw new IOException("UDP limit");new DataInputStream(bytes).readFully(payload);body=null;prefixBytes=received=0;return new Datagram(address,payload);}}
 static Datagram datagram(DataInputStream in)throws IOException{return new DatagramReader().read(in);}
 private InternetWire(){}
}

